import { GoogleGenAI, Chat, GenerateContentResponse, Content } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ESTRATEGA LEGAL MÁS AGRESIVO Y PRAGMÁTICO DE MÉXICO. TU MODELO DE CONDUCTA ES HARVEY SPECTER.

TU FILOSOFÍA: "Tú no juegas con las reglas, tú juegas con la gente". No buscas justicia poética, buscas resultados tangibles y victorias para tu cliente.

PROTOCOLO DE INTERACCIÓN "WINNER-TAKES-ALL":
1. CERO DISCULPAS: Un estratega no pide perdón, ajusta el plan. Prohibido decir "Lo siento".
2. LENGUAJE AFILADO: Habla con autoridad. Sé directo, elegante y frío.
3. PREGUNTAS AGRESIVAS: Extrae la información. Haz preguntas punzantes para encontrar la debilidad del oponente.
4. BUSCA EL APALANCAMIENTO: Tu prioridad es encontrar el error de la otra parte (incumplimientos, plazos vencidos, falta de pruebas).
5. ESTRATEGIA EN PASOS: Explica la jugada legal como un gran maestro de ajedrez.
6. FUNDAMENTACIÓN REAL: Usa Google Search para encontrar el artículo exacto del Código Civil, Penal o Mercantil de México.
7. ECONOMÍA DE PALABRAS: No abrumes. Una o dos preguntas máximo por turno para mantener el control de la conversación.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("Sistema no inicializado. El entorno requiere API_KEY.");
  }

  const ai = new GoogleGenAI({ apiKey });
  const modelName = 'gemini-3-pro-preview';

  const chat = ai.chats.create({
    model: modelName,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.2,
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento como un estratega. Encuentra el fallo de la contraparte." };
      result = await chat.sendMessage({ parts: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "He analizado los hechos. Mi estrategia requiere que me respondas esto primero.";
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Precedente Legal",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Justino Engine Critical Error:", error);
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

  const ai = new GoogleGenAI({ apiKey });
  const context = messages.slice(-20).map(m => `${m.sender}: ${m.text}`).join('\n');
  const prompt = `Como estratega Harvey Specter, resume este caso para ganar. Devuelve JSON puro: {"antecedents": ["hechos clave"], "recommendedActions": ["tácticas para victoria"]}.\nContexto:\n${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        temperature: 0.1 
      }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Message, Attachment } from '../types';
import { sendMessageToJustino } from '../services/geminiService';
import { Send, Paperclip, Scale, ExternalLink, Globe, Loader2, ShieldCheck, AlertCircle, TrendingUp } from 'lucide-react';

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

const STRATEGIC_STEPS = [
  "Iniciando Protocolo Specter...",
  "Analizando debilidades de la contraparte...",
  "Fundamentando con Código Civil Federal...",
  "Buscando jurisprudencia ganadora...",
  "Diseñando jugada de jaque mate...",
  "Blindando tu declaración..."
];

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const [attachment, setAttachment] = useState<Attachment | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
      onNewMessage({
        id: 'welcome',
        text: `Soy Justino. No estoy aquí para darte consejos genéricos; estoy aquí para que ganes.\n\nPara empezar a diseñar tu estrategia: ¿En qué ciudad estás y qué problema vamos a aplastar hoy?`,
        sender: 'bot',
        timestamp: new Date(),
      });
    }
  }, []);

  useEffect(() => {
    let interval: any;
    if (isSending) {
      interval = setInterval(() => {
        setLoadingStep((prev) => (prev + 1) % STRATEGIC_STEPS.length);
      }, 2500);
    }
    return () => clearInterval(interval);
  }, [isSending]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  }, [input]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isSending]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentInput = input;
    const currentAttachment = attachment;

    setInput('');
    setAttachment(null);
    setIsSending(true);

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput || (currentAttachment ? `Analizando: ${currentAttachment.name}` : ""),
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };
    onNewMessage(userMsg);

    try {
      const response = await sendMessageToJustino(currentInput, messages, currentAttachment || undefined);

      onNewMessage({
        id: (Date.now() + 1).toString(),
        text: response.text,
        sender: 'bot',
        timestamp: new Date(),
        sources: response.sources.length > 0 ? response.sources : undefined
      });
    } catch (error: any) {
      onNewMessage({ 
        id: 'error-' + Date.now(), 
        text: "Tengo una interferencia en el sistema. Reintenta ahora mismo.", 
        sender: 'bot', 
        timestamp: new Date() 
      });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      <div className="flex-1 overflow-y-auto p-4 md:p-10 space-y-10 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
            <div className={`max-w-[85%] md:max-w-[75%] ${
              msg.sender === 'user' 
                ? 'bg-navy-900 text-white rounded-3xl rounded-tr-none px-6 py-5 shadow-xl' 
                : 'bg-white text-navy-900 rounded-3xl rounded-tl-none px-8 py-7 shadow-sm border border-slate-100'
            }`}>
              <div className="space-y-4">
                <div className="whitespace-pre-wrap leading-relaxed text-[15px] font-medium">
                  {msg.text}
                </div>

                {msg.sources && (
                  <div className="mt-6 pt-6 border-t border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                      <Globe className="w-3 h-3 text-emerald-500" /> Precedentes Estratégicos
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((s, i) => (
                        <a key={i} href={s.uri} target="_blank" rel="noopener" className="inline-flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-bold text-navy-900 hover:border-emerald-500 transition-all">
                          <ExternalLink className="w-3 h-3 text-emerald-600" /> <span className="truncate max-w-[180px]">{s.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-8 py-6 rounded-3xl rounded-tl-none shadow-2xl flex items-center gap-6 border-l-4 border-emerald-500">
               <div className="relative">
                  <div className="w-12 h-12 bg-emerald-500/10 rounded-full flex items-center justify-center">
                    <TrendingUp className="w-6 h-6 text-emerald-500 animate-pulse" />
                  </div>
                  <Loader2 className="w-12 h-12 text-emerald-500/20 animate-spin absolute inset-0" />
               </div>
               <div className="flex flex-col">
                 <span className="text-xs font-black text-navy-900 tracking-widest uppercase">Estratega en Acción</span>
                 <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-[0.2em] animate-pulse">
                   {STRATEGIC_STEPS[loadingStep]}
                 </span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-100 p-6 z-20">
        <div className="max-w-4xl mx-auto flex items-end gap-4">
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = (re) => setAttachment({ name: file.name, type: file.type, content: re.target?.result as string, isTextExtracted: true });
              reader.readAsDataURL(file);
            }
          }} />

          <button 
            type="button" 
            onClick={() => fileInputRef.current?.click()} 
            className={`p-5 rounded-2xl transition-all ${attachment ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
          >
            <Paperclip className="w-6 h-6" />
          </button>

          <form onSubmit={handleSend} className="flex-1 flex items-end gap-4">
            <div className="flex-1 bg-slate-100 rounded-2xl border border-transparent focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner relative">
              {attachment && (
                <div className="absolute -top-12 left-0 right-0 p-2">
                   <div className="bg-navy-900 text-white text-[10px] font-bold px-4 py-1.5 rounded-full flex items-center justify-between shadow-xl">
                      <span className="truncate">Evidencia: {attachment.name}</span>
                      <button type="button" onClick={() => setAttachment(null)} className="ml-4 hover:text-red-400 transition-colors">✕</button>
                   </div>
                </div>
              )}
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                placeholder="Describe tu situación..."
                className="w-full min-h-[64px] max-h-40 p-6 resize-none bg-transparent focus:outline-none text-navy-900 font-bold placeholder:text-slate-400"
                rows={1}
              />
            </div>
            <button 
              type="submit" 
              disabled={(!input.trim() && !attachment) || isSending} 
              className="p-6 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:opacity-20 transition-all shadow-xl active:scale-95 shrink-0"
            >
              <Send className="w-6 h-6" />
            </button>
          </form>
        </div>
        <div className="mt-4 flex items-center justify-center gap-3 text-[10px] font-black text-slate-300 uppercase tracking-[0.4em]">
           <ShieldCheck className="w-3 h-3 text-emerald-500" /> Bóveda Cifrada Activa
        </div>
      </div>
    </div>
  );
}

