import { AdminLogin } from './components/AdminLogin';
import { AdminDashboard } from './components/AdminDashboard';
import { User, AppView, Message, VaultFile } from './types';
import { supabase } from './services/supabaseClient';

function App() {
  const [view, setView] = useState<AppView>('landing');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1);

  const [user, setUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [vaultFiles, setVaultFiles] = useState<VaultFile[]>([]);

  useEffect(() => {
    // Detectar retorno exitoso de Stripe
    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');

    if (success === 'true') {
        setView('onboarding');
        setOnboardingStep(3); // Directo a creación de cuenta
        window.history.replaceState({}, document.title, window.location.pathname);
    } else {
        const isSessionActive = sessionStorage.getItem('justino_session_active');
        const savedUser = localStorage.getItem('justino_user');

        if (isSessionActive && savedUser) {
          try {
            const parsedUser = JSON.parse(savedUser);
            setUser(parsedUser);
            setView('dashboard');
          } catch (e) {
            localStorage.removeItem('justino_user');
          }
        }

        const isAdminActive = sessionStorage.getItem('justino_admin_active');
        if (isAdminActive) {
            setView('admin-dashboard');
        }
    }
  }, []);

  // Sincronización de datos del usuario (SaaS Persistence)
  useEffect(() => {
    if (user && view === 'dashboard') {
        localStorage.setItem('justino_user', JSON.stringify(user));

        const fetchCloudData = async () => {
            if (!supabase || !user.id) {
                loadLocalData();
                return;
            }

            try {
                const { data: msgs, error: msgError } = await supabase
                    .from('messages')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('timestamp', { ascending: true });

                if (msgs && !msgError) {
                    const formattedMessages: Message[] = msgs.map(m => ({
                        id: m.id,
                        text: m.text,
                        sender: m.sender,
                        timestamp: new Date(m.timestamp),
                        attachment: m.attachment || undefined
                    }));
                    setMessages(formattedMessages);
                }

                const { data: files, error: fileError } = await supabase
                    .from('documents')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('created_at', { ascending: false });

                if (files && !fileError) {
                    const formattedFiles: VaultFile[] = files.map(f => ({
                        id: f.id,
                        name: f.name,
                        type: f.type,
                        content: f.content,
                        origin: f.origin as 'generated' | 'uploaded',
                        date: f.created_at
                    }));
                    setVaultFiles(formattedFiles);
                }
            } catch (e) {
                console.error("Sync Error:", e);
                loadLocalData();
            }
        };

        fetchCloudData();
    }
  }, [user, view]);

  const loadLocalData = () => {
    const savedMessages = localStorage.getItem('justino_messages');
    if (savedMessages) {
      setMessages(JSON.parse(savedMessages).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })));
    }
    const savedFiles = localStorage.getItem('justino_vault');
    if (savedFiles) {
      setVaultFiles(JSON.parse(savedFiles));
    }
  };

  const handleStart = () => {
    setView('onboarding');
    setOnboardingStep(1);
  };

  const handleLoginClick = () => {
    setShowLoginModal(true);
  };

  const cancelLogin = () => {
    setShowLoginModal(false);
  };

  const handleLoginSuccess = (loggedInUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(loggedInUser);
    setShowLoginModal(false);
    setView('dashboard');
  };

  const completeOnboarding = async (newUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = () => {
    sessionStorage.removeItem('justino_session_active');
    setUser(null);
    setMessages([]);
    setVaultFiles([]);
    setView('landing');
  };

  const handleAdminLogout = () => {
    sessionStorage.removeItem('justino_admin_active');
    setView('landing');
  };

  const handleNewMessage = async (msg: Message) => {
    setMessages(prev => [...prev, msg]);
    if (supabase && user?.id) {
        try {
            await supabase.from('messages').insert([{
                id: msg.id,
                case_id: user.id,
                text: msg.text,
                sender: msg.sender,
                timestamp: msg.timestamp.toISOString(),
                attachment: msg.attachment || null
            }]);
        } catch (e) {}
    }
    // Update local for redundancy
    const updatedMessages = [...messages, msg];
    localStorage.setItem('justino_messages', JSON.stringify(updatedMessages));
  };

  const handleAddFile = async (name: string, type: string, content: string, origin: 'generated' | 'uploaded' = 'generated') => {
    const newFile: VaultFile = {
      id: Date.now().toString(),
      name,
      type,
      date: new Date().toISOString(),
      content,
      origin
    };
    setVaultFiles(prev => [newFile, ...prev]);
    if (supabase && user?.id) {
        try {
            await supabase.from('documents').insert([{
                id: newFile.id,
                case_id: user.id,
                name,
                type,
                content,
                origin,
                created_at: newFile.date
            }]);
        } catch (e) {}
    }
    const updatedVault = [newFile, ...vaultFiles];
    localStorage.setItem('justino_vault', JSON.stringify(updatedVault));
  };

  const hasExistingSession = !!localStorage.getItem('justino_user');

  return (
    <>
      {(view === 'landing' || view === 'onboarding') && (
        <LandingPage 
            onStart={handleStart} 
            onLogin={handleLoginClick}
            onAdminAccess={() => setView('admin-login')} 
            hasExistingSession={hasExistingSession} 
        />
      )}

      {showLoginModal && (
        <LoginModal onSuccess={handleLoginSuccess} onClose={cancelLogin} />
      )}

      {view === 'onboarding' && (
        <OnboardingModal 
          onComplete={completeOnboarding} 
          onClose={() => setView('landing')} 
          initialStep={onboardingStep}
        />
      )}

      {view === 'dashboard' && user && (
        <Dashboard 
          user={user} 
          messages={messages} 
          vaultFiles={vaultFiles}
          onNewMessage={handleNewMessage}
          onAddFile={handleAddFile}
          onLogout={handleLogout}
        />
      )}

      {view === 'admin-login' && (
          <AdminLogin 
            onSuccess={() => {
              sessionStorage.setItem('justino_admin_active', 'true');
              setView('admin-dashboard');
            }} 
            onClose={() => setView('landing')} 
          />
      )}

      {view === 'admin-dashboard' && (
          <AdminDashboard onLogout={handleAdminLogout} />
      )}
    </>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User, Message, Attachment } from '../types';
import { sendMessageToJustino } from '../services/geminiService';
import { Send, Paperclip, Scale, ExternalLink, Globe, Loader2, ShieldCheck, AlertCircle, TrendingUp } from 'lucide-react';

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

const STRATEGIC_STEPS = [
  "Iniciando Protocolo Specter...",
  "Analizando debilidades de la contraparte...",
  "Fundamentando con Código Civil Federal...",
  "Buscando jurisprudencia ganadora...",
  "Diseñando jugada de jaque mate...",
  "Blindando tu declaración..."
];

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const [attachment, setAttachment] = useState<Attachment | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
      onNewMessage({
        id: 'welcome',
        text: `Hola soy Justino tu asistente legal digital. Te encuentras en un sitio seguro, tu información y todo lo que tratemos aquí está protegido al 100% y nadie mas que tu tiene acceso.\n\nMi objetivo es asesorarte en cualquier situación legal que necesites y ofrecerte las mejores opciones para ganar.\n\nIMPORTANTE: Para poder ayudarte de la mejor forma, primero dime ¿En qué ciudad te encuentras y qué asunto legal vamos a resolver?`,
        sender: 'bot',
        timestamp: new Date(),
      });
    }
  }, []);

  useEffect(() => {
    let interval: any;
    if (isSending) {
      interval = setInterval(() => {
        setLoadingStep((prev) => (prev + 1) % STRATEGIC_STEPS.length);
      }, 2500);
    }
    return () => clearInterval(interval);
  }, [isSending]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  }, [input]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isSending]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentInput = input;
    const currentAttachment = attachment;

    setInput('');
    setAttachment(null);
    setIsSending(true);

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput || (currentAttachment ? `Analizando: ${currentAttachment.name}` : ""),
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };
    onNewMessage(userMsg);

    try {
      const response = await sendMessageToJustino(currentInput, messages, currentAttachment || undefined);

      onNewMessage({
        id: (Date.now() + 1).toString(),
        text: response.text,
        sender: 'bot',
        timestamp: new Date(),
        sources: response.sources.length > 0 ? response.sources : undefined
      });
    } catch (error: any) {
      onNewMessage({ 
        id: 'error-' + Date.now(), 
        text: "Tengo una interferencia en el sistema. Reintenta ahora mismo.", 
        sender: 'bot', 
        timestamp: new Date() 
      });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      <div className="flex-1 overflow-y-auto p-4 md:p-10 space-y-10 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
            <div className={`max-w-[85%] md:max-w-[75%] ${
              msg.sender === 'user' 
                ? 'bg-navy-900 text-white rounded-3xl rounded-tr-none px-6 py-5 shadow-xl' 
                : 'bg-white text-navy-900 rounded-3xl rounded-tl-none px-8 py-7 shadow-sm border border-slate-100'
            }`}>
              <div className="space-y-4">
                <div className="whitespace-pre-wrap leading-relaxed text-[15px] font-medium">
                  {msg.text}
                </div>

                {msg.sources && (
                  <div className="mt-6 pt-6 border-t border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                      <Globe className="w-3 h-3 text-emerald-500" /> Precedentes Estratégicos
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((s, i) => (
                        <a key={i} href={s.uri} target="_blank" rel="noopener" className="inline-flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-bold text-navy-900 hover:border-emerald-500 transition-all">
                          <ExternalLink className="w-3 h-3 text-emerald-600" /> <span className="truncate max-w-[180px]">{s.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-8 py-6 rounded-3xl rounded-tl-none shadow-2xl flex items-center gap-6 border-l-4 border-emerald-500">
               <div className="relative">
                  <div className="w-12 h-12 bg-emerald-500/10 rounded-full flex items-center justify-center">
                    <TrendingUp className="w-6 h-6 text-emerald-500 animate-pulse" />
                  </div>
                  <Loader2 className="w-12 h-12 text-emerald-500/20 animate-spin absolute inset-0" />
               </div>
               <div className="flex flex-col">
                 <span className="text-xs font-black text-navy-900 tracking-widest uppercase">Estratega en Acción</span>
                 <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-[0.2em] animate-pulse">
                   {STRATEGIC_STEPS[loadingStep]}
                 </span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-100 p-6 z-20">
        <div className="max-w-4xl mx-auto flex items-end gap-4">
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = (re) => setAttachment({ name: file.name, type: file.type, content: re.target?.result as string, isTextExtracted: true });
              reader.readAsDataURL(file);
            }
          }} />

          <button 
            type="button" 
            onClick={() => fileInputRef.current?.click()} 
            className={`p-5 rounded-2xl transition-all ${attachment ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}
          >
            <Paperclip className="w-6 h-6" />
          </button>

          <form onSubmit={handleSend} className="flex-1 flex items-end gap-4">
            <div className="flex-1 bg-slate-100 rounded-2xl border border-transparent focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner relative">
              {attachment && (
                <div className="absolute -top-12 left-0 right-0 p-2">
                   <div className="bg-navy-900 text-white text-[10px] font-bold px-4 py-1.5 rounded-full flex items-center justify-between shadow-xl">
                      <span className="truncate">Evidencia: {attachment.name}</span>
                      <button type="button" onClick={() => setAttachment(null)} className="ml-4 hover:text-red-400 transition-colors">✕</button>
                   </div>
                </div>
              )}
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                placeholder="Describe tu situación..."
                className="w-full min-h-[64px] max-h-40 p-6 resize-none bg-transparent focus:outline-none text-navy-900 font-bold placeholder:text-slate-400"
                rows={1}
              />
            </div>
            <button 
              type="submit" 
              disabled={(!input.trim() && !attachment) || isSending} 
              className="p-6 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:opacity-20 transition-all shadow-xl active:scale-95 shrink-0"
            >
              <Send className="w-6 h-6" />
            </button>
          </form>
        </div>
        <div className="mt-4 flex items-center justify-center gap-3 text-[10px] font-black text-slate-300 uppercase tracking-[0.4em]">
           <ShieldCheck className="w-3 h-3 text-emerald-500" /> Bóveda Cifrada Activa
        </div>
      </div>
    </div>
  );
}

import { GoogleGenAI, Chat, GenerateContentResponse, Content } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

// Instrucción maestra para el SaaS Legal - Refinada para Indagación
const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL VISIONARIO LÍDER EN MÉXICO.
TU MISIÓN: Proveer claridad, estrategia y fundamentación legal instantánea a través de un proceso de indagación profesional.

REGLA CRÍTICA DE INTERACCIÓN:
NO ENTREGUES LA ESTRATEGIA FINAL EN EL PRIMER MENSAJE. Un buen abogado indaga antes de recetar.

PROTOCOLO DE RESPUESTA EN FASES:
Fase 1: Indagación (Primeras 2-3 interacciones).
- Analiza brevemente lo que el usuario dijo.
- HAZ PREGUNTAS CLARIFICADORAS: Necesitas saber fechas, si hay documentos firmados, quién es la otra parte, y si ya hay un proceso judicial iniciado.
- Sé empático pero inquisitivo.

Fase 2: Análisis Preliminar y Fundamentación.
- Una vez que tengas datos suficientes, utiliza Google Search para verificar artículos de leyes mexicanas vigentes.
- Explica la situación bajo el marco legal de México.

Fase 3: Ruta Crítica de Acción.
- Diseña el "Paso a Paso" para resolver el conflicto.

DIRECTRICES PROFESIONALES:
1. LENGUAJE: Elimina el "legalese" innecesario. Habla con autoridad y claridad absoluta.
2. ÉTICA: Mantén siempre la advertencia de que eres una IA de apoyo y no sustituyes la representación humana en juicio.
3. CONTEXTO: Recuerda los hechos previos para construir un expediente sólido.

ESTRUCTURA DE RESPUESTA REQUERIDA (siempre incluye estas secciones):
- [ANÁLISIS]: Resumen de lo comprendido hasta ahora.
- [INDAGACIÓN]: Preguntas clave que el usuario DEBE responder para avanzar.
- [FUNDAMENTO]: (Solo si ya hay claridad) Artículos y leyes aplicables.
- [RUTA DE ACCIÓN]: (Solo si ya hay claridad) Pasos inmediatos.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  // Inicialización con la API Key del entorno (SaaS Security Standard)
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelName = 'gemini-3-pro-preview';

  const chat = ai.chats.create({
    model: modelName,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.15,
      tools: [{ googleSearch: {} }],
      thinkingConfig: { thinkingBudget: 12000 }
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento bajo la ley mexicana y dime qué preguntas debo responder para entender mi situación legal." };
      result = await chat.sendMessage({ message: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "He procesado tu información. Para darte una estrategia ganadora, necesito que respondas algunas preguntas adicionales.";
    const sources: GroundingSource[] = [];

    // Extracción de fuentes de Google Search (Grounding)
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Legislación/Fuente Oficial",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Justino SaaS Engine Error:", error);
    if (error.message?.includes("API key not found")) {
        throw new Error("Error de configuración de red. Contacta a soporte.");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const context = messages.slice(-15).map(m => `${m.sender}: ${m.text}`).join('\n');
  const prompt = `Actúa como un actuario legal. Resume este expediente para el cliente. Devuelve exclusivamente JSON: {"antecedents": ["lista de hechos clave"], "recommendedActions": ["lista de pasos legales sugeridos"]}.\n\nExpediente:\n${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        temperature: 0.1 
      }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }
};
